  /* ----- src/ui/titre.js ----- */
  "<div class=\"titre-entete\"><h1>Nouvelle Fortune</h1><p class=\"sous-titre\">Dix-huit ans, une ville, rien dans les poches. Survivre, s'élever, transmettre.</p>": "<div class=\"titre-entete\"><h1>Nouvelle Fortune</h1><p class=\"sous-titre\">Eighteen years old, a city, nothing in your pockets. Survive, rise, pass it on.</p>",
  "<div class=\"panneau\"><h2>Jouer</h2>": "<div class=\"panneau\"><h2>Play</h2>",
  "<div class=\"carte\"><div class=\"carte-titre\"><span class=\"carte-icone\">💾</span><strong>Partie en cours</strong></div>": "<div class=\"carte\"><div class=\"carte-titre\"><span class=\"carte-icone\">💾</span><strong>Game in progress</strong></div>",
  "▶ Continuer": "▶ Continue",
  "<div class=\"carte\"><div class=\"carte-titre\"><span class=\"carte-icone\">🌃</span><strong>Nouvelle partie</strong></div>": "<div class=\"carte\"><div class=\"carte-titre\"><span class=\"carte-icone\">🌃</span><strong>New game</strong></div>",
  "<div class=\"carte-desc\">Chaque graine génère une ville, un personnage et un marché de l'emploi différents. Laissez vide pour une graine aléatoire.</div>": "<div class=\"carte-desc\">Each seed generates a different city, character and job market. Leave blank for a random seed.</div>",
